// ============================================================================
// MIPI_SLIMbus_apb: APB4 register wrapper around MIPI_SLIMbus_top (generated by
// scripts/apb/gen_apb.py from scripts/apb/specs/MIPI_SLIMbus.json; do not edit)
// ----------------------------------------------------------------------------
//  - APB4 slave, zero wait states (PREADY = PSEL & PENABLE), 32-bit data,
//    12-bit byte address; PSLVERR on an unmapped or misaligned access.
//  - PSTRB byte lanes apply to every writable register.
//  - The core runs on PCLK/PRESETN; protocol pins pass through unchanged.
//  - Register map: docs/ip/MIPI_SLIMbus.md
// ============================================================================
module MIPI_SLIMbus_apb (
  input  logic        PCLK,
  input  logic        PRESETN,
  input  logic        PSEL,
  input  logic        PENABLE,
  input  logic        PWRITE,
  input  logic [11:0] PADDR,
  input  logic [31:0] PWDATA,
  input  logic [3:0]  PSTRB,
  output logic [31:0] PRDATA,
  output logic        PREADY,
  output logic        PSLVERR,
  output logic        irq,
  output logic slim_clk_o,
  output logic slim_clk_oe,
  input logic slim_clk_i,
  output logic slim_dat_o,
  output logic slim_dat_oe,
  input logic slim_dat_i
);
  localparam logic [31:0] ID_VALUE = 32'h534C0200;

  // ---------------- APB decode ----------------
  wire        acc     = PSEL & PENABLE;
  wire        wr      = acc & PWRITE;
  wire        rd      = acc & ~PWRITE;
  wire [31:0] wmask   = {{8{PSTRB[3]}}, {8{PSTRB[2]}}, {8{PSTRB[1]}}, {8{PSTRB[0]}}};
  logic [10:0] hit;
  always_comb begin
    hit = '0;
    if (PADDR[1:0] == 2'b00 && PADDR[11:2] < 10'd11) hit[PADDR[11:2]] = 1'b1;
  end
  assign PREADY  = acc;
  assign PSLVERR = acc & ~|hit;

  // ---------------- core ----------------
  logic          c_cfg_framer;
  logic [3:0]    c_cfg_div;
  logic [7:0]    c_cfg_fi;
  logic          c_sf_set;
  logic [15:0]   c_sf_set_val;
  logic [7:0]    c_cfg_tx_slot;
  logic [2:0]    c_cfg_tx_len;
  logic [7:0]    c_cfg_rx_slot;
  logic [2:0]    c_cfg_rx_len;
  logic          c_cfg_err;
  logic          c_tx_valid;
  logic          c_tx_ready;
  logic [31:0]   c_tx_data;
  logic          c_tx_underrun;
  logic          c_rx_valid;
  logic [31:0]   c_rx_data;
  logic          c_rx_err;
  logic          c_locked;
  logic          c_sf_locked;
  logic          c_lost_sync;
  logic          c_fi_valid;
  logic [7:0]    c_fi_info;
  logic [15:0]   c_sf_count;
  MIPI_SLIMbus_top u_core (
    .clk(PCLK),
    .rst_n(PRESETN),
    .cfg_framer(c_cfg_framer),
    .cfg_div(c_cfg_div),
    .cfg_fi(c_cfg_fi),
    .sf_set(c_sf_set),
    .sf_set_val(c_sf_set_val),
    .cfg_tx_slot(c_cfg_tx_slot),
    .cfg_tx_len(c_cfg_tx_len),
    .cfg_rx_slot(c_cfg_rx_slot),
    .cfg_rx_len(c_cfg_rx_len),
    .cfg_err(c_cfg_err),
    .slim_clk_o(slim_clk_o),
    .slim_clk_oe(slim_clk_oe),
    .slim_clk_i(slim_clk_i),
    .slim_dat_o(slim_dat_o),
    .slim_dat_oe(slim_dat_oe),
    .slim_dat_i(slim_dat_i),
    .tx_valid(c_tx_valid),
    .tx_ready(c_tx_ready),
    .tx_data(c_tx_data),
    .tx_underrun(c_tx_underrun),
    .rx_valid(c_rx_valid),
    .rx_data(c_rx_data),
    .rx_err(c_rx_err),
    .locked(c_locked),
    .sf_locked(c_sf_locked),
    .lost_sync(c_lost_sync),
    .fi_valid(c_fi_valid),
    .fi_info(c_fi_info),
    .sf_count(c_sf_count)
  );

  // ---------------- registers ----------------
  logic [7:0] irq_status, irq_enable, irq_set;
  logic [31:0] scratch;
  logic [12:0] r_CFG;   // 12'h014 CFG
  logic [21:0] r_CHAN;   // 12'h018 CHAN
  logic [15:0] h_SFSET;   // 12'h01C SFSET holding register
  logic [31:0] h_TX;   // 12'h020 TX holding register
  logic [31:0] h_RX;   // 12'h024 RX holding register
  logic vld_SFSET;
  logic full_TX;
  logic avail_RX;

  always_ff @(posedge PCLK or negedge PRESETN) begin
    if (!PRESETN) begin
      irq_status <= '0; irq_enable <= '0; scratch <= '0;
      r_CFG <= 13'h6;
      r_CHAN <= 22'h801;
      h_SFSET <= '0;
      h_TX <= '0;
      h_RX <= '0;
      vld_SFSET <= 1'b0;
      full_TX <= 1'b0;
      avail_RX <= 1'b0;
    end else begin
      irq_status <= (irq_status & ~((wr && hit[1]) ? PWDATA[7:0] & wmask[7:0] : '0)) | irq_set;
      if (wr && hit[2]) irq_enable <= (irq_enable & ~wmask[7:0]) | (PWDATA[7:0] & wmask[7:0]);
      if (wr && hit[4]) scratch <= (scratch & ~wmask) | (PWDATA & wmask);
      if (wr && hit[5]) r_CFG <= (r_CFG & ~wmask[12:0]) | (PWDATA[12:0] & wmask[12:0]);
      if (wr && hit[6]) r_CHAN <= (r_CHAN & ~wmask[21:0]) | (PWDATA[21:0] & wmask[21:0]);
      if (wr && hit[7]) h_SFSET <= (h_SFSET & ~wmask[15:0]) | (PWDATA[15:0] & wmask[15:0]);
      vld_SFSET <= wr && hit[7];
      if (wr && hit[8] && !full_TX) h_TX <= (h_TX & ~wmask[31:0]) | (PWDATA[31:0] & wmask[31:0]);
      if (wr && hit[8] && !full_TX) full_TX <= 1'b1;
      else if (full_TX && c_tx_ready) full_TX <= 1'b0;
      if (c_rx_valid && (!avail_RX || (rd && hit[9]))) begin
        h_RX[31:0] <= c_rx_data[31:0];
        avail_RX <= 1'b1;
      end else if (rd && hit[9]) avail_RX <= 1'b0;
    end
  end

  // ---------------- core inputs ----------------
  assign c_cfg_framer = r_CFG[0:0];
  assign c_cfg_div = r_CFG[4:1];
  assign c_cfg_fi = r_CFG[12:5];
  assign c_cfg_tx_slot = r_CHAN[7:0];
  assign c_cfg_tx_len = r_CHAN[10:8];
  assign c_cfg_rx_slot = r_CHAN[18:11];
  assign c_cfg_rx_len = r_CHAN[21:19];
  assign c_sf_set_val[15:0] = h_SFSET[15:0];
  assign c_tx_data[31:0] = h_TX[31:0];
  assign c_sf_set = vld_SFSET;
  assign c_tx_valid = full_TX;

  // ---------------- interrupts and flags ----------------
  always_comb begin
    irq_set = '0;
    irq_set[0] = c_fi_valid;
    irq_set[1] = c_lost_sync;
    irq_set[2] = c_tx_underrun;
    irq_set[3] = c_rx_err;
    irq_set[4] = full_TX & c_tx_ready;
    irq_set[5] = wr & (hit[8]) & full_TX;
    irq_set[6] = c_rx_valid & (~avail_RX | (rd & hit[9]));
    irq_set[7] = c_rx_valid & avail_RX & ~(rd & hit[9]);
  end
  assign irq = |(irq_status & irq_enable);
  wire [1:0] flags = {avail_RX, full_TX};

  // ---------------- read mux ----------------
  logic [31:0] rdata;
  always_comb begin
    rdata = '0;
    case (PADDR[11:2])
      10'd0: rdata = ID_VALUE;
      10'd1: rdata = 32'(irq_status);
      10'd2: rdata = 32'(irq_enable);
      10'd3: rdata = 32'(flags);
      10'd4: rdata = scratch;
      10'd5: rdata = 32'(r_CFG);
      10'd6: rdata = 32'(r_CHAN);
      10'd7: rdata = 32'(h_SFSET);
      10'd8: rdata = 32'(h_TX);
      10'd9: rdata = 32'(h_RX);
      10'd10: rdata = 32'({c_sf_count, c_fi_info, c_cfg_err, c_sf_locked, c_locked});
      default: rdata = '0;
    endcase
  end
  assign PRDATA = (rd && |hit) ? rdata : '0;
endmodule
